_m $'<account ID>.r2.cloudflarestorage.com, shown on the R2 overview page' $'<Konto-ID>.r2.cloudflarestorage.com, wird auf der R2-Übersichtsseite angezeigt'
_m $'for instance {1}' $'zum Beispiel {1}'
